   136	// killPinnedMarkedProcess signals pid only through a pidfd opened on it,
   137	// after the environment read through that same pinned process still holds
   138	// entry.
   139	func killPinnedMarkedProcess(pid int, entry []byte) error {
   140		fd, err := unix.PidfdOpen(pid, 0)
   141		if errors.Is(err, unix.ESRCH) {
   142			return nil
   143		}
   144		if err != nil {
   145			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
   146		}
   147		defer unix.Close(fd)
   148		// The pidfd names one process for its lifetime; if pid was reused before
   149		// it was opened, the new process does not carry this run's entry.
   150		marked, err := reviewProcessMarked(pid, entry)
   151		if reviewProcessGoneErr(err) || err == nil && !marked {
   152			return nil
   153		}
   154		if err != nil {
   155			return fmt.Errorf("process %d could not be inspected: %w", pid, err)
   156		}
   157		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil && !errors.Is(err, unix.ESRCH) {
   158			return fmt.Errorf("process %d could not be ended: %w", pid, err)
   159		}
   160		return nil
   161	}
