   200	func reviewProcessZombie(pid int) (bool, error) {
   201		raw, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
   202		if err != nil {
   203			return false, err
   204		}
   205		// The state follows the parenthesised command name.
   206		if i := bytes.LastIndexByte(raw, ')'); i >= 0 && i+2 < len(raw) {
   207			return raw[i+2] == 'Z', nil
   208		}
   209		return false, fmt.Errorf("process %d state is unreadable", pid)
   210	}
