   213	func delegationStepText(e DelegationEvent) string {
   214		text := strings.Join(strings.Fields(e.Text), " ")
   215		if len(text) > 80 {
   216			cut := 77
   217			for cut > 0 && !utf8RuneStart(text[cut]) {
   218				cut--
   219			}
   220			text = text[:cut] + "..."
   221		}
   222		switch e.Kind {
   223		case DelegationEventToolCall:
   224			return "▶ " + text
   225		case DelegationEventToolOutput:
   226			if e.ExitCode != nil && *e.ExitCode != 0 {
   227				return fmt.Sprintf("✗ exit %d", *e.ExitCode)
   228			}
   229			return "✓ exit 0"
   230		case DelegationEventTurn:
   231			return "turn"
   232		}
   233		if text == "" {
   234			return e.Kind
   235		}
   236		return e.Kind + ": " + text
   237	}
