215	// killPinnedChild signals pid through a pidfd while it is still a child of
216	// parent: a pid reused by an unrelated process is never signalled.
217	func killPinnedChild(pid, parent int) error {
218		fd, err := unix.PidfdOpen(pid, 0)
219		if errors.Is(err, unix.ESRCH) {
220			return nil
221		}
222		if err != nil {
223			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
224		}
225		defer unix.Close(fd)
226		st, err := readShimProcStat(pid)
227		if reviewProcessGoneErr(err) || err == nil && st.ppid != parent {
228			return nil
229		}
230		if err != nil {
231			return fmt.Errorf("process %d could not be inspected: %w", pid, err)
232		}
233		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil && !errors.Is(err, unix.ESRCH) {
234			return fmt.Errorf("process %d could not be ended: %w", pid, err)
235		}
236		return nil
237	}
