   165	// writeDeadMarker rewrites the marker of attempt so its owner is a process
   166	// that has exited and its heartbeat is an hour old, as a dispatch killed
   167	// mid-run leaves it.
   168	func writeDeadMarker(t *testing.T, s Store, attempt string) {
   169		t.Helper()
   170		dir, err := s.delegationActiveDir(false)
   171		if err != nil {
   172			t.Fatal(err)
   173		}
   174		path := filepath.Join(dir, attempt+".json")
   175		raw, err := os.ReadFile(path)
   176		if err != nil {
   177			t.Fatal(err)
   178		}
   179		var marker DelegationActiveRun
   180		if err := json.Unmarshal(raw, &marker); err != nil {
   181			t.Fatal(err)
   182		}
   183		dead := exec.Command("true")
   184		if err := dead.Run(); err != nil {
   185			t.Fatal(err)
   186		}
   187		old := time.Now().Add(-time.Hour).UTC().Format(time.RFC3339Nano)
   188		marker.Owner.PID, marker.HeartbeatAt, marker.StartedAt = dead.Process.Pid, old, old
   189		raw, _ = json.Marshal(marker)
   190		if err := os.WriteFile(path, raw, 0o600); err != nil {
   191			t.Fatal(err)
   192		}
   193	}
